content:
The archaeologist sweep is digging through `.hermes` bloat and the workflow alias isn’t found because the dashboard uses `bash`, not `zsh`. Let’s fix both: filter out bloat/excluded files using your existing `bloat_exclusions.lst` and embed the workflow reference directly into the dashboard.

---

## 🛡️ Step 1 – Embed Workflow Quick Reference

We’ll replace the `subprocess.run(['bash', '-c', 'workflow'])` with a printed card.

```bash
sed -i '/elif choice == '\''6'\'':/,+1c\        elif choice == '\''6'\'':\n            print(f"""{C}╔══════════════════════════════════════════════╗{N}\n{C}║  4_51GH7 ForeSight — Command Quick Reference  ║{N}\n{C}╚══════════════════════════════════════════════╝{N}\n\nResearch a file'\''s history   archaeo <file>\nCheck impact before change  oracle <file>\nMake a change               dispatch-queue   (recommended, 1 at a time)\n                            dispatch-parallel (2+ TMUX windows, use sparingly)\n                            task-watch        (background polling)\nValidate & promote           validate_promotion.py → promote\nRebuild indices              map-build && map-func && fore\nList pending tasks           task-list\nShow this reference          workflow""")' ~/archwiz/archwiz.py
```

---

## 🧹 Step 2 – Exclude Bloat from Archaeologist Sweep

Update the sweep to read `bloat_exclusions.lst` and skip matching files, plus handle Ctrl+C gracefully.

```bash
cat > ~/archwiz/archaeo_sweep.py << 'PYEOF'
#!/usr/bin/env python3
"""Sweep changed files, skipping bloat and excluded directories."""
import json, os, signal, subprocess, sys
from pathlib import Path
from datetime import datetime, timezone

HOME = Path.home()
STATE_FILE = HOME / 'archwiz/archaeo_state.json'
ARCHAEO = HOME / 'workspace/llm_map/archaeologist.py'
TASK_INDEX = HOME / 'workspace/llm_map/task_files_index.json'
METRICS_LOG = HOME / 'workspace/llm_map/metrics_log.jsonl'
BLOAT_LIST = HOME / 'workspace/llm_map/bloat_exclusions.lst'

# Always skip these directories
HARD_SKIP = {'.hermes', '__pycache__', '.git', 'node_modules', 'target', 'Cargo.lock'}

def load_state():
    if STATE_FILE.exists():
        return json.loads(STATE_FILE.read_text())
    return {}

def save_state(state):
    STATE_FILE.parent.mkdir(parents=True, exist_ok=True)
    STATE_FILE.write_text(json.dumps(state, indent=2))

def file_mtime(rel_path):
    p = HOME / rel_path
    return p.stat().st_mtime if p.exists() else 0

def load_bloat_patterns():
    patterns = set()
    if BLOAT_LIST.exists():
        for line in BLOAT_LIST.read_text().splitlines():
            line = line.strip()
            if line and not line.startswith('#'):
                patterns.add(line)
    return patterns

def get_tracked_files():
    """Derive files from task_files_index.json or metrics_log.jsonl, then filter bloat."""
    files = set()
    # Prefer task_files_index
    if TASK_INDEX.exists():
        try:
            data = json.loads(TASK_INDEX.read_text())
            for category, items in data.items():
                if isinstance(items, list):
                    for entry in items:
                        f = entry.get('file') or entry.get('target_file')
                        if f:
                            files.add(f)
                elif isinstance(items, dict):
                    for f, info in items.items():
                        if isinstance(info, dict):
                            ff = info.get('file') or info.get('target_file')
                            if ff: files.add(ff)
                        elif isinstance(info, str):
                            files.add(info)
        except Exception:
            pass
    # Fallback: unique files from metrics_log
    if not files and METRICS_LOG.exists():
        with open(METRICS_LOG) as mf:
            for line in mf:
                try:
                    obj = json.loads(line)
                    f = obj.get('file')
                    if f:
                        files.add(f)
                except:
                    pass
    # Filter out bloat
    bloat = load_bloat_patterns()
    filtered = []
    for f in sorted(files):
        parts = Path(f).parts
        # hard skip
        if any(skip in parts for skip in HARD_SKIP):
            continue
        # check bloat patterns (simple substring match)
        if any(pattern in f for pattern in bloat):
            continue
        filtered.append(f)
    return filtered

def sweep():
    signal.signal(signal.SIGINT, lambda s, f: sys.exit(0))
    state = load_state()
    now = datetime.now(timezone.utc).isoformat()
    tracked = get_tracked_files()
    if not tracked:
        print("No tracked files found (or all excluded). Run an oracle scan first.")
        return
    scanned = 0
    skipped = 0
    for f in tracked:
        mtime = file_mtime(f)
        last = state.get(f, {}).get('last_mtime', 0)
        if mtime <= last:
            skipped += 1
            continue
        print(f"\n{'='*60}")
        print(f"🔍 Scanning: {f}")
        subprocess.run(['python3', str(ARCHAEO), f, '--full'])
        state[f] = {'last_mtime': mtime, 'last_scan': now}
        scanned += 1
    if scanned == 0:
        print("\n✅ No files changed since last sweep. All quiet.")
    else:
        print(f"\n🏺 Sweep complete: {scanned} files scanned, {skipped} skipped.")
    save_state(state)

if __name__ == '__main__':
    sweep()
PYEOF
chmod +x ~/archwiz/archaeo_sweep.py
```

Now `[2]` will skip `.hermes`, `__pycache__`, and anything in your bloat list. `[6]` prints the quick reference instantly.

